import {serve} from '@hono/node-server';import {serveStatic} from '@hono/node-server/serve-static';import {Hono} from 'hono';import {z} from 'zod';import {calculate,type RequestInput} from './logic.js';
declare const process:{env:Record<string,string|undefined>};const maxBodyBytes=16_384;const schema=z.object({assay_ref:z.string(),inlet_vials:z.number().int(),outlet_vials:z.number().int(),reagent_cartridges:z.number().int(),assay_benches:z.number().int(),contamination_alert:z.boolean(),repeated_submission:z.boolean()}).strict();
const response=(value:unknown,status=200,headers:Record<string,string>={})=>{if(Object.keys(headers).some(name=>['content-length','content-type','connection','transfer-encoding','x-content-type-options'].includes(name.toLowerCase())))return new Response(JSON.stringify({error:'invalid_response_headers',detail:'server-owned response header'}),{status:500,headers:{'content-type':'application/json'}});return new Response(JSON.stringify(value),{status,headers:{'content-type':'application/json',...headers}})};const error=(code:string,status:number,detail:string)=>response({error:code,detail},status);const zero=(v:RequestInput,state:string)=>({assay_ref:v.assay_ref,sample_tally:0,assay_effort:0,bench_allowance:0,examined_effort:0,pending_assay:0,assay_cycles:0,assay_rating:0,assay_phase:state});const decide=(v:RequestInput,headers:Headers)=>{if((headers.get('authorization')??'')!=="Sample sample-046")return response(zero(v,'authorization_required'),401,{"www-authenticate":"Sample realm=estuary"});if([v.inlet_vials,v.outlet_vials,v.reagent_cartridges,v.assay_benches].some(item=>item<0))return response(zero(v,'invalid'),422,{'x-validation':'nonnegative'});if(v.assay_benches===0&&v.inlet_vials+v.outlet_vials>0)return response(zero(v,'invalid'),422,{'x-validation':'assay_benches'});if(v.repeated_submission)return response(zero(v,'duplicate'),409,{'x-conflict':'repeated_submission'});return response(calculate(v),200,{});};
const app=new Hono();app.get('/status/estuary-assay-ready',()=>response({service:'Estuary Assay Dispatch',ready:true}));app.post('/api/v10/estuary-assays',async context=>{const media=(context.req.header('content-type')??'').split(';',1)[0]!.trim().toLowerCase();if(media!=='application/json'&&!media.endsWith('+json'))return error('json_content_type_required',415,'expected application/json');const declared=context.req.header('content-length');if(declared&&(!/^\d+$/.test(declared)||Number(declared)>maxBodyBytes))return error('body_too_large',413,'request body exceeds 16384 bytes');const raw=await context.req.arrayBuffer();if(raw.byteLength>maxBodyBytes)return error('body_too_large',413,'request body exceeds 16384 bytes');try{const parsed=schema.safeParse(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw)));if(!parsed.success)return error('invalid_json',400,parsed.error.message);return decide(parsed.data,context.req.raw.headers)}catch(caught){return error('invalid_json',400,String(caught))}});app.all('/api/*',context=>error('not_found',404,`no API route ${context.req.path}`));app.get('/parley.js',serveStatic({path:process.env.FULLSTACK_046_BROWSER??'./dist/logic.js'}));app.get('/*',serveStatic({root:'./public'}));serve({fetch:app.fetch,hostname:'127.0.0.1',port:Number(process.env.PARLEY_WEB_PORT)});
